from __future__ import annotations

import hashlib
import json
import shutil
import subprocess
from dataclasses import asdict, dataclass, field
from datetime import datetime, timezone
from pathlib import Path
from typing import Any, Dict, List, Optional, Tuple

try:
    import cv2
    import numpy as np
except Exception:  # pragma: no cover
    cv2 = None
    np = None


def _now() -> str:
    return datetime.now(timezone.utc).isoformat()


def _file_sha1(path: str, chunk: int = 1024 * 1024) -> str:
    h = hashlib.sha1()
    with open(path, "rb") as f:
        while True:
            b = f.read(chunk)
            if not b:
                break
            h.update(b)
    return h.hexdigest()


def _hamming(a: str, b: str) -> int:
    n = min(len(a), len(b))
    if n == 0:
        return 999
    return sum(x != y for x, y in zip(a[:n], b[:n])) + abs(len(a) - len(b))


@dataclass
class DuplicateGroup:
    group_id: str
    representative: str
    duplicates: List[str]
    score: float
    reason: str
    members: List[str] = field(default_factory=list)

    def to_dict(self) -> Dict[str, Any]:
        d = asdict(self)
        d["members"] = self.members or [self.representative] + self.duplicates
        return d


@dataclass
class DedupReport:
    input_count: int
    unique_count: int
    duplicate_count: int
    dedup_rate: float
    unique_assets: List[str]
    duplicate_groups: List[DuplicateGroup]
    created_at: str = field(default_factory=_now)

    def to_dict(self) -> Dict[str, Any]:
        d = asdict(self)
        d["duplicate_groups"] = [g.to_dict() for g in self.duplicate_groups]
        return d

    def to_markdown(self) -> str:
        rows = "\n".join(
            f"| {g.group_id} | `{g.representative}` | {len(g.duplicates)} | {g.score:.3f} | {g.reason} |"
            for g in self.duplicate_groups
        ) or "| - | - | 0 | - | 无重复 |"
        return f"""# VSC22去重报告

- 输入素材数：{self.input_count}
- 去重后素材数：{self.unique_count}
- 重复素材数：{self.duplicate_count}
- 去重率：{self.dedup_rate:.2%}
- 生成时间：{self.created_at}

| 分组 | 代表素材 | 重复数 | 相似度 | 原因 |
|---|---|---:|---:|---|
{rows}
"""


class FrameDedup:
    def __init__(self, max_frames: int = 16, hash_threshold: int = 10, ssim_threshold: float = 0.90):
        self.max_frames = max_frames
        self.hash_threshold = hash_threshold
        self.ssim_threshold = ssim_threshold

    def available(self) -> bool:
        return cv2 is not None and np is not None

    def extract_keyframes(self, video_path: str) -> List[Any]:
        if not self.available():
            return []
        cap = cv2.VideoCapture(str(video_path))
        if not cap.isOpened():
            return []
        total = int(cap.get(cv2.CAP_PROP_FRAME_COUNT) or 0)
        if total <= 0:
            total = self.max_frames
        positions = np.linspace(0, max(0, total - 1), self.max_frames).astype(int).tolist()
        frames = []
        for pos in positions:
            cap.set(cv2.CAP_PROP_POS_FRAMES, int(pos))
            ok, frame = cap.read()
            if ok and frame is not None:
                frames.append(frame)
        cap.release()
        return frames

    def phash(self, frame: Any) -> str:
        if not self.available():
            return ""
        gray = cv2.cvtColor(frame, cv2.COLOR_BGR2GRAY) if len(frame.shape) == 3 else frame
        small = cv2.resize(gray, (32, 32), interpolation=cv2.INTER_AREA).astype("float32")
        dct = cv2.dct(small)
        low = dct[:8, :8].flatten()
        med = float(np.median(low[1:])) if len(low) > 1 else float(np.median(low))
        return "".join("1" if x > med else "0" for x in low)

    def hashes(self, video_path: str) -> List[str]:
        return [self.phash(f) for f in self.extract_keyframes(video_path)]

    def ssim(self, a: Any, b: Any) -> float:
        if not self.available():
            return 0.0
        if len(a.shape) == 3:
            a = cv2.cvtColor(a, cv2.COLOR_BGR2GRAY)
        if len(b.shape) == 3:
            b = cv2.cvtColor(b, cv2.COLOR_BGR2GRAY)
        a = cv2.resize(a, (160, 90), interpolation=cv2.INTER_AREA).astype("float32")
        b = cv2.resize(b, (160, 90), interpolation=cv2.INTER_AREA).astype("float32")
        c1, c2 = 6.5025, 58.5225
        mu1, mu2 = a.mean(), b.mean()
        var1, var2 = a.var(), b.var()
        cov = ((a - mu1) * (b - mu2)).mean()
        val = ((2 * mu1 * mu2 + c1) * (2 * cov + c2)) / ((mu1**2 + mu2**2 + c1) * (var1 + var2 + c2))
        return max(0.0, min(1.0, float(val)))

    def compare_hash_sequence(self, a: List[str], b: List[str]) -> float:
        if not a or not b:
            return 0.0
        if len(a) > len(b):
            a, b = b, a
        best = 0.0
        for off in range(0, max(1, len(b) - len(a) + 1)):
            pairs = zip(a, b[off:off + len(a)])
            sims = [1.0 - min(64, _hamming(x, y)) / 64.0 for x, y in pairs]
            if sims:
                best = max(best, sum(sims) / len(sims))
        return best

    def compare(self, video_a: str, video_b: str) -> Dict[str, Any]:
        frames_a = self.extract_keyframes(video_a)
        frames_b = self.extract_keyframes(video_b)
        hashes_a = [self.phash(x) for x in frames_a]
        hashes_b = [self.phash(x) for x in frames_b]
        hash_score = self.compare_hash_sequence(hashes_a, hashes_b)
        ssim_vals = [self.ssim(x, y) for x, y in zip(frames_a[:6], frames_b[:6])]
        ssim_score = sum(ssim_vals) / len(ssim_vals) if ssim_vals else 0.0
        score = max(hash_score, 0.6 * hash_score + 0.4 * ssim_score)
        return {"score": round(score, 4), "hash_score": round(hash_score, 4), "ssim_score": round(ssim_score, 4)}


class VideoDedup:
    def __init__(
        self,
        video_threshold: float = 0.86,
        exact_threshold: float = 0.98,
        frame_dedup: Optional[FrameDedup] = None,
    ):
        self.video_threshold = video_threshold
        self.exact_threshold = exact_threshold
        self.frame_dedup = frame_dedup or FrameDedup()
        self._cache: Dict[str, Dict[str, Any]] = {}

    def fingerprint(self, video_path: str) -> Dict[str, Any]:
        path = str(video_path)
        if path in self._cache:
            return self._cache[path]
        p = Path(path)
        item = {
            "path": path,
            "size": p.stat().st_size if p.exists() else 0,
            "sha1": _file_sha1(path) if p.exists() else "",
            "phash_seq": self.frame_dedup.hashes(path),
            "chromaprint": self._chromaprint(path),
        }
        self._cache[path] = item
        return item

    def _chromaprint(self, video_path: str) -> str:
        fpcalc = shutil.which("fpcalc")
        if fpcalc:
            try:
                out = subprocess.check_output([fpcalc, "-json", video_path], stderr=subprocess.DEVNULL, timeout=30)
                data = json.loads(out.decode("utf-8", errors="ignore"))
                return str(data.get("fingerprint", ""))
            except Exception:
                pass
        if not self.frame_dedup.available():
            return ""
        frames = self.frame_dedup.extract_keyframes(video_path)
        chunks = []
        for frame in frames[:12]:
            small = cv2.resize(frame, (32, 32), interpolation=cv2.INTER_AREA)
            hist = cv2.calcHist([small], [0, 1, 2], None, [4, 4, 4], [0, 256, 0, 256, 0, 256])
            hist = cv2.normalize(hist, hist).flatten()
            chunks.append("".join(format(int(x * 15), "x")[-1] for x in hist[:32]))
        return "|".join(chunks)

    def _chromaprint_score(self, a: str, b: str) -> float:
        if not a or not b:
            return 0.0
        if a == b:
            return 1.0
        parts_a, parts_b = a.split("|"), b.split("|")
        if len(parts_a) > len(parts_b):
            parts_a, parts_b = parts_b, parts_a
        best = 0.0
        for off in range(0, max(1, len(parts_b) - len(parts_a) + 1)):
            sims = []
            for x, y in zip(parts_a, parts_b[off:off + len(parts_a)]):
                n = max(len(x), len(y), 1)
                sims.append(1.0 - _hamming(x, y) / n)
            if sims:
                best = max(best, sum(sims) / len(sims))
        return max(0.0, min(1.0, best))

    def compare(self, video_a: str, video_b: str) -> Dict[str, Any]:
        fa, fb = self.fingerprint(video_a), self.fingerprint(video_b)
        if fa["sha1"] and fa["sha1"] == fb["sha1"]:
            return {"score": 1.0, "reason": "sha1_exact"}
        phash_score = self.frame_dedup.compare_hash_sequence(fa["phash_seq"], fb["phash_seq"])
        chroma_score = self._chromaprint_score(fa["chromaprint"], fb["chromaprint"])
        frame_score = self.frame_dedup.compare(video_a, video_b)["score"] if self.frame_dedup.available() else phash_score
        score = 0.45 * phash_score + 0.35 * chroma_score + 0.20 * frame_score
        reason = f"phash={phash_score:.3f}, chroma={chroma_score:.3f}, frame={frame_score:.3f}"
        return {"score": round(score, 4), "reason": reason}

    def dedup(self, asset_paths: List[str]) -> DedupReport:
        unique: List[str] = []
        groups: List[DuplicateGroup] = []
        assigned: Dict[str, str] = {}

        for path in asset_paths:
            if path in assigned:
                continue
            best_rep, best_score, best_reason = None, 0.0, ""
            for rep in unique:
                cmp = self.compare(path, rep)
                if cmp["score"] > best_score:
                    best_rep, best_score, best_reason = rep, cmp["score"], cmp["reason"]

            if best_rep and best_score >= self.video_threshold:
                group = next((g for g in groups if g.representative == best_rep), None)
                if not group:
                    group = DuplicateGroup(
                        group_id=f"group_{len(groups) + 1}",
                        representative=best_rep,
                        duplicates=[],
                        score=best_score,
                        reason=best_reason,
                    )
                    groups.append(group)
                group.duplicates.append(path)
                group.members = [group.representative] + group.duplicates
                group.score = max(group.score, best_score)
                assigned[path] = group.group_id
            else:
                unique.append(path)
                assigned[path] = "unique"

        duplicate_count = sum(len(g.duplicates) for g in groups)
        total = len(asset_paths)
        return DedupReport(
            input_count=total,
            unique_count=len(unique),
            duplicate_count=duplicate_count,
            dedup_rate=(duplicate_count / total) if total else 0.0,
            unique_assets=unique,
            duplicate_groups=groups,
        )


__all__ = ["VideoDedup", "FrameDedup", "DedupReport", "DuplicateGroup"]
